#!/usr/bin/env python3
"""ZYN Empire — bootstrap.py
Run on the GCP VM (or anywhere): python3 bootstrap.py
Generates all 10 production files of the autonomous agent stack.
"""
import os, base64, sys
from pathlib import Path

FILES = [
    ("requirements.txt", ""),
    (".env.example", ""),
    ("agents_config.json", ""),
    ("llm_router.py", ""),
    ("tools.py", ""),
    ("zyn_agent.py", ""),
    ("orchestrator.py", ""),
    ("test_connection.py", ""),
    ("ecosystem.config.js", ""),
    (".github/workflows/deploy.yml", ""),
]

def main():
    here = Path(__file__).parent.resolve()
    written = 0
    for rel, data_b64 in FILES:
        target = here / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        content = base64.b64decode(data_b64).decode("utf-8")
        target.write_text(content, encoding="utf-8")
        print(f"  wrote {target.relative_to(here)}  ({len(content):>7} bytes)")
        written += 1
    # ensure logs directory exists
    (here / "logs").mkdir(exist_ok=True)
    print(f"\n✅ ZYN Empire scaffold ready — {written} files written under {here}")
    print(f"\nNext:")
    print(f"  1. cp .env.example .env && edit .env")
    print(f"  2. pip3 install -r requirements.txt")
    print(f"  3. python3 test_connection.py")
    print(f"  4. pm2 start ecosystem.config.js && pm2 save")

if __name__ == "__main__":
    main()
